type TripQueueRow = typeof schema.tripQueue.$inferSelect;

function toTripQueue(row: TripQueueRow): z.infer<typeof tripQueueShape> {
  let stops: string[] = [];
  try {
    const parsed: unknown = JSON.parse(row.stopsJson);
    if (Array.isArray(parsed)) stops = parsed.filter((x): x is string => typeof x === "string");
  } catch {
    stops = [];
  }
  return {
    id: row.id,
    name: row.name,
    origin: row.origin ?? null,
    destination: row.destination ?? null,
    status: row.status,
    loadId: row.loadId ?? null,
    notes: row.notes ?? null,
    payRate: row.payRate,
    payBasis: row.payBasis === "percent" ? "percent" : "cpm",
    payPercent: row.payPercent ?? null,
    extraCharges: row.extraCharges ?? 0,
    extraChargesNote: row.extraChargesNote ?? null,
    stops,
    routeLabel: row.routeLabel ?? null,
    startedAt: row.startedAt?.toISOString() ?? null,
    endedAt: row.endedAt?.toISOString() ?? null,
    completedTripId: row.completedTripId ?? null,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

