// ---- Equipment families (migration 0026) -----------------------------------
// The pickup photo's subject follows the equipment type. Open family
// (flatbed / open deck / RGN / oversized): the load slot is "Load +
// securement" — chains/straps/tarp shown, extra angles allowed.
// Enclosed family (dry van / reefer / container): the load slot is
// "Seal photo — seal locked on the door" plus the seal-number confirm.
const EQUIPMENT_TYPES: Record<string, { label: string; family: "open" | "enclosed" }> = {
  flatbed: { label: "Flatbed", family: "open" },
  open_deck: { label: "Open deck", family: "open" },
  rgn: { label: "RGN", family: "open" },
  oversized: { label: "Oversized", family: "open" },
  dry_van: { label: "Dry van", family: "enclosed" },
  reefer: { label: "Reefer", family: "enclosed" },
  container: { label: "Container", family: "enclosed" },
};
function equipmentFamilyOf(type: string | null | undefined): "open" | "enclosed" | null {
  if (!type) return null;
  return EQUIPMENT_TYPES[type]?.family ?? null;
}
/** Comparison state for the seal-number confirm. Both numbers present:
 *  match or mismatch (a mismatch is a real stored state, shown plainly).
 *  Only one present: entered_only / bol_only. Neither: null. */
function sealStatusFor(entered: string | null, bol: string | null): string | null {
  const norm = (s: string | null) => (s ? s.trim().toUpperCase() : "");
  const e = norm(entered);
  const b = norm(bol);
  if (e && b) return e === b ? "match" : "mismatch";
  if (e) return "entered_only";
  if (b) return "bol_only";
  return null;
}

// Per-criterion results of the release-grade POD seal evaluation
// (server/src/sealGrade.ts) — carried on the load so the tracker, the
// load views, and the Settlement Checker can show the grade.
const sealGradeCriteriaShape = z.object({
  tightGeofence: z.object({ pass: z.boolean(), distanceMi: z.number().nullable(), radiusMi: z.number() }),
  bolFingerprinted: z.object({ pass: z.boolean(), sha256: z.string().nullable() }),
  noOpenExceptions: z.object({ pass: z.boolean(), detail: z.string() }),
  gpsFixQuality: z.object({
    pass: z.boolean(),
    detail: z.string(),
    accepted: z.number().nullable(),
    goodShare: z.number().nullable(),
  }),
});

// Instant Pay Phase 0 Payment Packet summary on the load (records
// only — no money state of any kind rides on a packet).
