type BoardLoadRow = typeof schema.boardLoads.$inferSelect;

function toBoardLoad(
  row: BoardLoadRow,
  linked: { status: string; podSealed: boolean; hasPickupProof: boolean } | null,
): z.infer<typeof boardLoadShape> {
  let canUnassign = false;
  let blocked: string | null = null;
  if (row.status === "taken") {
    if (!linked) {
      blocked = "The driver's load for this board post is gone, so there is nothing to hand back — withdraw and repost it fresh if it still needs covering.";
    } else if (linked.podSealed) {
      blocked = "Already delivered and POD-sealed — a sealed delivery can't be unassigned.";
    } else if (linked.status !== "booked") {
      blocked = "Already picked up — unassigning is only for loads that haven't reached pickup yet.";
    } else if (linked.hasPickupProof) {
      blocked = "Pickup proof is already on file for this load — it has reached the pickup step, so it can't go back on the board.";
    } else {
      canUnassign = true;
    }
  }
  return {
    id: row.id,
    companyId: row.companyId,
    postedBy: row.postedBy,
    shipper: row.shipper,
    pickupCity: row.pickupCity,
    pickupState: row.pickupState,
    deliveryCity: row.deliveryCity,
    deliveryState: row.deliveryState,
    pickupText: row.pickupText,
    deliveryText: row.deliveryText,
    rate: row.rate,
    loadedMiles: row.loadedMiles ?? null,
    milesSource: row.milesSource ?? null,
    ...perMileFor(row.rate, row.extraCharges ?? 0, row.loadedMiles ?? null),
    extraCharges: row.extraCharges ?? 0,
    extraChargesNote: row.extraChargesNote ?? null,
    totalWithExtras: row.rate != null ? Math.round((row.rate + (row.extraCharges ?? 0)) * 100) / 100 : null,
    weightLbs: row.weightLbs,
    commodity: row.commodity,
    hazmat: row.hazmat ?? false,
    equipmentType: row.equipmentType ?? null,
    equipmentLabel: row.equipmentType ? (EQUIPMENT_TYPES[row.equipmentType]?.label ?? row.equipmentType) : null,
    notes: row.notes ?? null,
    status: row.status,
    claimMethod: row.claimMethod ?? null,
    claimedBy: row.claimedBy ?? null,
    claimedAt: row.claimedAt?.toISOString() ?? null,
    loadId: row.loadId ?? null,
    tripQueueId: row.tripQueueId ?? null,
    linkedLoadStatus: linked?.status ?? null,
    linkedPodSealed: linked?.podSealed ?? false,
    canUnassign,
    unassignBlockedReason: blocked,
    hasDoc: row.docBlobKey != null,
    docSha256: row.docSha256 ?? null,
    docMime: row.docMime ?? null,
    brokerName: row.brokerName ?? null,
    brokerCompany: row.brokerCompany ?? null,
    brokerMc: row.brokerMc ?? null,
    brokerSource: row.brokerSource ?? null,
    boardScope: row.boardScope ?? "fleet",
    originKind: row.originKind ?? null,
    originLabel: row.originLabel ?? null,
    dispatcherFeePct: row.dispatcherFeePct ?? null,
    vettedOnly: row.vettedOnly ?? false,
    overflowReason: row.overflowReason ?? null,
    overflowOpenBoardId: null,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

/** Live state of the driver load a taken board row created. */
async function boardLinkedState(
  ctx: Ctx,
  row: BoardLoadRow,
): Promise<{ status: string; podSealed: boolean; hasPickupProof: boolean } | null> {
  if (row.loadId == null) return null;
  const db = ctx.db<typeof schema>();
  const rows = await db.select().from(schema.loads).where(eq(schema.loads.id, row.loadId)).limit(1);
  const load = rows[0];
  if (!load) return null;
  const pods = await podStatusByLoad(ctx);
  return {
    status: load.status,
    podSealed: pods.get(load.id)?.sealed ?? false,
    hasPickupProof: load.pickupLoadBlobKey != null || load.pickupBolBlobKey != null || load.pickupSealedAt != null,
  };
}

/**
 * Create the driver's real load (Booked) + its trip from a board row —
 * the same records the solo "Add a load" flow creates, so the Load
 * Tracker, routing, pickup proof, and POD seal all work unchanged.
 * The trip's pay basis/rate inherit the DRIVER's own saved pay setup
 * exactly like createTripQueue (their company CPM, else $0.55/mi).
 * In this single-device staging build the profile row is the local
 * account's; at the accounts release the same inheritance reads the
 * claiming driver's own profile — the board row and the created load
 * are what carry over.
 */
async function createLoadFromBoard(
  ctx: Ctx,
  board: BoardLoadRow,
  driverUsername: string,
): Promise<{ loadId: number; tripQueueId: number }> {
  const db = ctx.db<typeof schema>();
  const profRows = await db.select().from(schema.profile).where(eq(schema.profile.id, myProfileId(ctx))).limit(1);
  const prof = profRows[0];
  const fields = {
    shipper: board.shipper,
    pickupCity: board.pickupCity,
    pickupState: board.pickupState,
    deliveryCity: board.deliveryCity,
    deliveryState: board.deliveryState,
    pickupText: board.pickupText,
    deliveryText: board.deliveryText,
    rate: board.rate,
    weightLbs: board.weightLbs,
    commodity: board.commodity,
    hazmat: board.hazmat ?? false,
  };
  // Loaded miles ride onto the driver's load so its $/mi matches the
  // board card the driver claimed from (migration 0080).
  const ins = await db
    .insert(schema.loads)
    .values({
      ...fields,
      loadedMiles: board.loadedMiles ?? null,
      milesSource: board.milesSource ?? null,
      extraCharges: board.extraCharges ?? 0,
      extraChargesNote: board.extraChargesNote ?? null,
      docBlobKey: board.docBlobKey ?? null,
      docMime: board.docMime ?? null,
      docSha256: board.docSha256 ?? null,
      equipmentType: board.equipmentType ?? null,
      trailerNumber: prof?.currentTrailer ?? null,
      status: "booked",
      // Broker identity captured durably at creation (migration 0049):
      // copied from the board post, which got it from the broker link
      // (broker uploads) or the poster (manual board posts).
      brokerName: board.brokerName ?? null,
      brokerCompany: board.brokerCompany ?? null,
      brokerMc: board.brokerMc ?? null,
      brokerSource: board.brokerSource ?? null,
      brokerLinkId: board.brokerLinkId ?? null,
    })
    .returning({ id: schema.loads.id });
  const loadId = ins[0]?.id;
  if (loadId == null) throw new Error("createLoadFromBoard: load insert returned no rows");
  const claimSource = (board.boardScope ?? "fleet") === "open" ? "open_board" : "fleet_board";
  await appendChain(ctx, {
    refKind: "load",
    refId: loadId,
    sessionId: null,
    event: "load_saved",
    payload: { ...fields, extraCharges: board.extraCharges ?? 0, extraChargesNote: board.extraChargesNote ?? null, source: claimSource, boardLoadId: board.id, originKind: board.originKind ?? null, originLabel: board.originLabel ?? null, driver: driverUsername },
  });
  if (board.docSha256) {
    await appendChain(ctx, {
      refKind: "load",
      refId: loadId,
      sessionId: null,
      event: "doc_sealed",
      payload: { sha256: board.docSha256, mime: board.docMime, source: claimSource, boardLoadId: board.id },
    });
  }
  const lane = (city: string | null, state: string | null) => [city, state].filter(Boolean).join(", ");
  const tripName =
    `${lane(board.pickupCity, board.pickupState) || "Pickup"} → ${lane(board.deliveryCity, board.deliveryState) || "Delivery"}`.slice(0, 120);
  const payRate = prof?.driverCpm ?? 0.55;
  const payBasis = prof?.payBasis === "percent" ? "percent" : "cpm";
  const payPercent = payBasis === "percent" ? (prof?.driverPayPct ?? null) : null;
  const tq = await db
    .insert(schema.tripQueue)
    .values({
      name: tripName,
      origin: lane(board.pickupCity, board.pickupState) || null,
      destination: lane(board.deliveryCity, board.deliveryState) || null,
      status: "planned",
      loadId,
      notes: board.notes ?? null,
      payRate,
      payBasis,
      payPercent,
      extraCharges: board.extraCharges ?? 0,
      extraChargesNote: board.extraChargesNote ?? null,
      stopsJson: "[]",
    })
    .returning({ id: schema.tripQueue.id });
  const tripQueueId = tq[0]?.id;
  if (tripQueueId == null) throw new Error("createLoadFromBoard: trip insert returned no rows");
  await db.update(schema.loads).set({ tripQueueId }).where(eq(schema.loads.id, loadId));
  await appendChain(ctx, {
    refKind: "trip",
    refId: null,
    sessionId: null,
    event: "trip_queue_created",
    payload: { queueId: tripQueueId, name: tripName, loadId, source: claimSource, boardLoadId: board.id, driver: driverUsername, at: new Date().toISOString() },
  });
  return { loadId, tripQueueId };
}

/**
 * Atomically take an OPEN board row for a driver. The flip is ONE
 * conditional UPDATE (… WHERE status = 'open'): SQLite serializes the
 * statement, so of any two claims racing for the same load exactly one
 * matches the row — the loser updates nothing and is told the load is
 * already taken. Only after the flip lands do we create the driver's
 * load + trip; if that creation ever failed, the flip is rolled back
 * to open so the load is never stranded off the board.
 */
async function takeBoardLoad(
  ctx: Ctx,
  board: BoardLoadRow,
  driverUsername: string,
  method: "claim" | "assign",
  actor: string,
): Promise<{ ok: boolean; error: string | null; loadId: number | null; tripQueueId: number | null }> {
  const db = ctx.db<typeof schema>();
  const now = new Date();
  const flipped = await db
    .update(schema.boardLoads)
    .set({ status: "taken", claimMethod: method, claimedBy: driverUsername, claimedAt: now, updatedAt: now })
    .where(and(eq(schema.boardLoads.id, board.id), eq(schema.boardLoads.status, "open")))
    .returning({ id: schema.boardLoads.id });
  if (!flipped[0]) {
    const fresh = await db.select().from(schema.boardLoads).where(eq(schema.boardLoads.id, board.id)).limit(1);
    const by = fresh[0]?.claimedBy;
    return {
      ok: false,
      error: by
        ? `Already taken — @${by} got this load first. It's off the board; the open loads below are still up for grabs.`
        : "That load is no longer open — it may have been withdrawn or taken. Refresh the board and pick another.",
      loadId: null,
      tripQueueId: null,
    };
  }
  try {
    const takenRow: BoardLoadRow = { ...board, status: "taken", claimMethod: method, claimedBy: driverUsername, claimedAt: now };
    const { loadId, tripQueueId } = await createLoadFromBoard(ctx, takenRow, driverUsername);
    await db
      .update(schema.boardLoads)
      .set({ loadId, tripQueueId, updatedAt: new Date() })
      .where(eq(schema.boardLoads.id, board.id));
    await appendChain(ctx, {
      refKind: "load",
      refId: loadId,
      sessionId: null,
      event: method === "claim" ? "board_load_claimed" : "board_load_assigned",
      payload: {
        boardLoadId: board.id,
        companyId: board.companyId,
        driver: driverUsername,
        by: actor,
        method,
        loadId,
        tripQueueId,
        lane: `${board.pickupCity ?? "?"} → ${board.deliveryCity ?? "?"}`,
        at: new Date().toISOString(),
      },
    });
    return { ok: true, error: null, loadId, tripQueueId };
  } catch {
    // Roll the flip back — a failed creation must never eat a board load.
    await db
      .update(schema.boardLoads)
      .set({ status: "open", claimMethod: null, claimedBy: null, claimedAt: null, loadId: null, tripQueueId: null, updatedAt: new Date() })
      .where(eq(schema.boardLoads.id, board.id));
    return { ok: false, error: "Claiming hit a snag creating the load — nothing was taken and the load is back on the board. Try again.", loadId: null, tripQueueId: null };
  }
}

// ---- Broker upload links + approval queue (migration 0048) -----------------
// OPTIONAL, OFF by default. Eligible: Diamond owner-operators (solo —
// personal links + inbox; approving creates their OWN load at Booked)
// and Fleet/Owner accounts (company version — Owner toggles it on,
// Owner/Dispatch manage links and the inbox; approving posts to the
// Fleet Board with the document attached). Gold/Basic are NOT eligible
// and every broker action says so plainly. A broker link is
// UPLOAD-ONLY: the token actions (getBrokerUploadInfo /
// submitBrokerUpload) return and accept NOTHING but the upload itself —
// no board, drivers, other loads, prices, HOS, or documents. A
// submission NEVER reaches the board or a driver until a human with
// the right seat approves it. HONEST LIMIT (stated in the UI too):
// a broker outside the app opening the link rides on the standalone /
// public portal packaging (same step as the public portal address and
// the iOS install); inside this build the complete flow runs in-app,
// including a broker-view preview that shows exactly the upload-only
// form a broker gets.

const brokerLinkShape = z.object({
  id: z.number(),
  brokerName: z.string(),
  brokerCompany: z.string().nullable(),
  brokerContact: z.string().nullable(),
  brokerMc: z.string().nullable(),
  token: z.string(),
  status: z.string(), // active | expired | revoked
  expiresAt: z.string(),
  revokedAt: z.string().nullable(),
  createdBy: z.string(),
  createdAt: z.string(),
  submissionCount: z.number(),
  pendingCount: z.number(),
});

const brokerSubmissionShape = z.object({
  id: z.number(),
  linkId: z.number(),
  brokerName: z.string(),
  brokerCompany: z.string().nullable(),
  brokerMc: z.string().nullable(),
  brokerLinkLabel: z.string(), // "<broker name> — <broker company>" of the link used
  shipper: z.string().nullable(),
  pickupCity: z.string().nullable(),
  pickupState: z.string().nullable(),
  deliveryCity: z.string().nullable(),
  deliveryState: z.string().nullable(),
  pickupText: z.string().nullable(),
  deliveryText: z.string().nullable(),
  rate: z.number().nullable(),
  ...milesShapeFields,
  extraCharges: z.number(),
  extraChargesNote: z.string().nullable(),
  totalWithExtras: z.number().nullable(),
  weightLbs: z.number().nullable(),
  commodity: z.string().nullable(),
  hazmat: z.boolean(),
  equipmentType: z.string().nullable(),
  equipmentLabel: z.string().nullable(),
  notes: z.string().nullable(),
  status: z.string(), // pending | approved | rejected
  hasDoc: z.boolean(),
  docSha256: z.string().nullable(),
  docMime: z.string().nullable(),
  boardLoadId: z.number().nullable(),
  loadId: z.number().nullable(),
  tripQueueId: z.number().nullable(),
  reviewedBy: z.string().nullable(),
  reviewedAt: z.string().nullable(),
  reviewNote: z.string().nullable(),
  createdAt: z.string(),
  updatedAt: z.string(),
});

type BrokerLinkRow = typeof schema.brokerLinks.$inferSelect;
type BrokerSubmissionRow = typeof schema.brokerSubmissions.$inferSelect;

type BrokerCtx = {
  me: string;
  plan: string;
  membership: Awaited<ReturnType<typeof myMembership>>;
  mode: "fleet" | "solo";
  scopeKey: string;
  companyId: number | null;
  companyName: string | null;
  eligible: boolean;
  canManage: boolean; // may create/revoke links + review the inbox
  canToggle: boolean; // may flip the opt-in itself
};

/** Resolve the broker scope for the caller: a company membership means
 *  the fleet version (scope = the company); no membership means the
 *  solo version (scope = the driver themselves). Eligibility is plan +
 *  seat: Diamond/Owner plan, or an Owner/Dispatch seat in a fleet (the
 *  fleet runs on the Owner plan — dispatch operates the feature for the
 *  owner). A company DRIVER seat alone is never eligible: drivers see
 *  nothing of this feature until an approval posts a load. */
async function brokerContext(ctx: Ctx): Promise<BrokerCtx> {
  const me = await myUsername(ctx);
  const plan = await myPlan(ctx);
  const membership = await myMembership(ctx, me);
  const mode: "fleet" | "solo" = membership ? "fleet" : "solo";
  const scopeKey = membership ? `company:${membership.company.id}` : `user:${me}`;
  const eligible =
    isDiamondPlan(plan) || (membership != null && (membership.role === "owner" || membership.role === "dispatch"));
  const canManage = eligible && (membership ? membership.role === "owner" || membership.role === "dispatch" : true);
  // The opt-in itself is the owner's call: the fleet owner in fleet
  // mode, the owner-operator themselves in solo mode.
  const canToggle = eligible && (membership ? membership.role === "owner" : true);
  return {
    me,
    plan,
    membership,
    mode,
    scopeKey,
    companyId: membership?.company.id ?? null,
    companyName: membership?.company.name ?? null,
    eligible,
    canManage,
    canToggle,
  };
}

async function brokerEnabled(ctx: Ctx, scopeKey: string): Promise<boolean> {
  const db = ctx.db<typeof schema>();
  const rows = await db.select().from(schema.brokerOptins).where(eq(schema.brokerOptins.scopeKey, scopeKey)).limit(1);
  return rows[0]?.enabled ?? false;
}

function brokerToken(): string {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  return `brk_${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}`;
}

function brokerLinkStatus(row: BrokerLinkRow, now = new Date()): "active" | "expired" | "revoked" {
  if (row.revokedAt) return "revoked";
  if (row.expiresAt.getTime() <= now.getTime()) return "expired";
  return "active";
}

function toBrokerLink(row: BrokerLinkRow, subs: BrokerSubmissionRow[]): z.infer<typeof brokerLinkShape> {
  const mine = subs.filter((s) => s.linkId === row.id);
  return {
    id: row.id,
    brokerName: row.brokerName,
    brokerCompany: row.brokerCompany ?? null,
    brokerContact: row.brokerContact ?? null,
    brokerMc: row.brokerMc ?? null,
    token: row.token,
    status: brokerLinkStatus(row),
    expiresAt: row.expiresAt.toISOString(),
    revokedAt: row.revokedAt?.toISOString() ?? null,
    createdBy: row.createdBy,
    createdAt: row.createdAt.toISOString(),
    submissionCount: mine.length,
    pendingCount: mine.filter((s) => s.status === "pending").length,
  };
}

function toBrokerSubmission(
  row: BrokerSubmissionRow,
  link: BrokerLinkRow | null,
): z.infer<typeof brokerSubmissionShape> {
  return {
    id: row.id,
    linkId: row.linkId,
    brokerName: row.brokerName,
    brokerCompany: row.brokerCompany ?? null,
    brokerMc: row.brokerMc ?? null,
    brokerLinkLabel: link ? `${link.brokerName}${link.brokerCompany ? ` — ${link.brokerCompany}` : ""}` : `Link #${row.linkId}`,
    shipper: row.shipper,
    pickupCity: row.pickupCity,
    pickupState: row.pickupState,
    deliveryCity: row.deliveryCity,
    deliveryState: row.deliveryState,
    pickupText: row.pickupText,
    deliveryText: row.deliveryText,
    rate: row.rate,
    loadedMiles: row.loadedMiles ?? null,
    milesSource: row.milesSource ?? null,
    ...perMileFor(row.rate, row.extraCharges ?? 0, row.loadedMiles ?? null),
    extraCharges: row.extraCharges ?? 0,
    extraChargesNote: row.extraChargesNote ?? null,
    totalWithExtras: row.rate != null ? Math.round((row.rate + (row.extraCharges ?? 0)) * 100) / 100 : null,
    weightLbs: row.weightLbs,
    commodity: row.commodity,
    hazmat: row.hazmat ?? false,
    equipmentType: row.equipmentType ?? null,
    equipmentLabel: row.equipmentType ? (EQUIPMENT_TYPES[row.equipmentType]?.label ?? row.equipmentType) : null,
    notes: row.notes ?? null,
    status: row.status,
    hasDoc: row.docBlobKey != null,
    docSha256: row.docSha256 ?? null,
    docMime: row.docMime ?? null,
    boardLoadId: row.boardLoadId ?? null,
    loadId: row.loadId ?? null,
    tripQueueId: row.tripQueueId ?? null,
    reviewedBy: row.reviewedBy ?? null,
    reviewedAt: row.reviewedAt?.toISOString() ?? null,
    reviewNote: row.reviewNote ?? null,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

/** Load-document extraction for a broker submission: the SAME vision
 *  read the load flows use, run server-side at submit time with NO plan
 *  gate (the broker has no plan — the read is part of this feature).
 *  Only fills fields the broker left blank; anything the document
 *  doesn't show stays null. Failures are silent here — the submission
 *  stands on what the broker typed and the reviewer edits by hand. */
async function extractBrokerDoc(
  ctx: Ctx,
  dataBase64: string,
  mimeType: "image/jpeg" | "image/png",
): Promise<{
  shipper: string | null;
  pickupCity: string | null;
  pickupState: string | null;
  deliveryCity: string | null;
  deliveryState: string | null;
  pickupText: string | null;
  deliveryText: string | null;
  rate: number | null;
  miles: number | null;
  weightLbs: number | null;
  commodity: string | null;
} | null> {
  try {
    const extractionSchema = z.object({
      found: z.boolean().describe("True only if the document visibly contains load details."),
      shipper: z.string().nullable().describe("Shipper or broker name exactly as printed, else null"),
      pickupCity: z.string().nullable().describe("Pickup / origin city exactly as printed, else null"),
      pickupState: z.string().nullable().describe("Pickup state as the full US state name when shown, else null"),
      deliveryCity: z.string().nullable().describe("Delivery / destination city exactly as printed, else null"),
      deliveryState: z.string().nullable().describe("Delivery state as the full US state name when shown, else null"),
      pickupText: z.string().nullable().describe("Pickup date and time exactly as printed, else null"),
      deliveryText: z.string().nullable().describe("Delivery date/time or appointment exactly as printed, else null"),
      rate: z.number().nullable().describe("Total load rate / total pay in dollars as printed (number only), else null"),
      miles: z.number().nullable().describe("Loaded miles / distance for the lane as printed on the document (labelled miles, distance, or mi — number only), else null"),
      weightLbs: z.number().nullable().describe("Load weight in pounds as printed, else null"),
      commodity: z.string().nullable().describe("Commodity / freight description as printed, else null"),
    });
    const result = await ctx.inference.complete(
      "Read this document (a trucking rate confirmation, load sheet, or similar). Extract ONLY the load details that are visibly printed on it. Do not guess, infer, or fill in anything that is not shown: any detail that is not printed must be null. If the document contains no load details at all, report found as false and every detail as null.",
      { schema: extractionSchema, images: [{ dataBase64, mimeType, filename: "broker-load-document" }] },
    );
    if (!result.found) return null;
    return {
      shipper: result.shipper,
      pickupCity: result.pickupCity,
      pickupState: result.pickupState,
      deliveryCity: result.deliveryCity,
      deliveryState: result.deliveryState,
      pickupText: result.pickupText,
      deliveryText: result.deliveryText,
      rate: result.rate,
      miles: result.miles,
      weightLbs: result.weightLbs,
      commodity: result.commodity,
    };
  } catch {
    return null;
  }
}

/** Extended document read for rate-con / BOL cross-verification: the
 *  SAME vision read the load flows use, with the wider field set the
 *  cross-check compares (street addresses, pieces, printed seal
 *  number, itemized charges, reference numbers). Runs server-side
 *  wherever the document bytes are already in hand — a broker
 *  submit, a load save with a document attached, the camera-sealed
 *  pickup BOL photo, which arrives as bytes in submitPickupPhoto.
 *  Only what is visibly printed is reported; anything not printed
 *  stays null and the cross-check reports it missing — never guessed.
 *  Returns null when the read itself could not run (the caller then
 *  records no snapshot, and a later run says the side was never
 *  read); a completed read that found no load details returns
 *  found=false with every field null. */
async function extractDocFieldsExtended(
  ctx: Ctx,
  dataBase64: string,
  mimeType: "image/jpeg" | "image/png",
): Promise<{ found: boolean; fields: DocSideFields } | null> {
  try {
    const num = (label: string) =>
      z.number().nullable().describe(`${label} as printed (number only, no commas or $), else null`);
    const str = (label: string) =>
      z.string().nullable().describe(`${label} exactly as printed, else null`);
    const extractionSchema = z.object({
      found: z.boolean().describe("True only if the document visibly contains load details (a rate confirmation, bill of lading, load sheet, or similar)."),
      shipper: str("Shipper or broker name"),
      pickupAddress: str("Full pickup street address (street number, street, suite) without city/state"),
      pickupCity: str("Pickup / origin city"),
      pickupState: str("Pickup state as the full US state name when the document shows the state or its abbreviation"),
      deliveryAddress: str("Full delivery street address (street number, street, suite) without city/state"),
      deliveryCity: str("Delivery / destination city"),
      deliveryState: str("Delivery state as the full US state name when shown"),
      pickupText: str("Pickup date and time"),
      deliveryText: str("Delivery date/time or appointment"),
      rate: num("Total load rate / total pay in dollars"),
      weightLbs: num("Load weight in pounds"),
      commodity: str("Commodity / freight description"),
      pieces: num("Pieces / pallet / skid count"),
      sealNumber: str("Trailer seal number (labelled seal / seal # / seal no.). Never guess a seal number that is not printed"),
      chargesFuelSurcharge: num("Fuel surcharge amount in dollars when itemized separately"),
      chargesDetention: num("Detention amount in dollars when itemized separately"),
      chargesLumper: num("Lumper fee amount in dollars when itemized separately"),
      chargesOther: num("Other accessorial charges in dollars when itemized separately (excluding fuel surcharge, detention, lumper)"),
      chargesTotal: num("Total additional / accessorial charges in dollars when the document prints a total for them"),
      loadNumber: str("Load number / load ID reference printed on the document"),
      poNumber: str("PO number printed on the document"),
      proNumber: str("PRO number printed on the document"),
    });
    const result = await ctx.inference.complete(
      "Read this document (a trucking rate confirmation, bill of lading, or load sheet). Extract ONLY the details that are visibly printed on it. Do not guess, infer, or fill in anything that is not shown: any detail that is not printed must be null. If the document contains no load details at all, report found as false and every detail as null.",
      {
        schema: extractionSchema,
        images: [{ dataBase64, mimeType, filename: "cross-verification-document" }],
      },
    );
    if (!result.found) return { found: false, fields: { ...EMPTY_DOC_FIELDS } };
    return {
      found: true,
      fields: {
        identity: result.shipper,
        pickupAddress: result.pickupAddress,
        pickupCity: result.pickupCity,
        pickupState: result.pickupState,
        deliveryAddress: result.deliveryAddress,
        deliveryCity: result.deliveryCity,
        deliveryState: result.deliveryState,
        pickupWindow: result.pickupText,
        deliveryWindow: result.deliveryText,
        commodity: result.commodity,
        weightLbs: result.weightLbs,
        pieces: result.pieces,
        sealNumber: result.sealNumber,
        rate: result.rate,
        chargesFuelSurcharge: result.chargesFuelSurcharge,
        chargesDetention: result.chargesDetention,
        chargesLumper: result.chargesLumper,
        chargesOther: result.chargesOther,
        chargesTotal: result.chargesTotal,
        loadNumber: result.loadNumber,
        poNumber: result.poNumber,
        proNumber: result.proNumber,
      },
    };
  } catch {
    return null;
  }
}

/** Parse a stored extraction snapshot's field set; a malformed row
 *  reads as an empty field set (never throws into a run). */
function parseDocFields(json: string): DocSideFields {
  try {
    const parsed = JSON.parse(json) as Partial<DocSideFields>;
    return { ...EMPTY_DOC_FIELDS, ...parsed };
  } catch {
    return { ...EMPTY_DOC_FIELDS };
  }
}

/** Record one document read as the latest extraction snapshot for a
 *  load side. History is kept (every read is a row + a chain event);
 *  a run reads the LATEST row for the side whose fingerprint matches
 *  the document currently attached — so re-attaching a corrected
 *  document supersedes the old read for the new document. */
async function recordDocExtraction(
  ctx: Ctx,
  args: {
    loadId: number;
    side: "ratecon" | "bol";
    source: "document" | "confirmed" | "load_record";
    docSha256: string | null;
    found: boolean;
    fields: DocSideFields;
  },
): Promise<void> {
  const db = ctx.db<typeof schema>();
  await db.insert(schema.loadDocExtractions).values({
    loadId: args.loadId,
    side: args.side,
    source: args.source,
    docSha256: args.docSha256,
    found: args.found,
    fieldsJson: JSON.stringify(args.fields),
  });
  await appendChain(ctx, {
    refKind: "load",
    refId: args.loadId,
    sessionId: null,
    event: "doc_extraction_recorded",
    payload: {
      loadId: args.loadId,
      side: args.side,
      source: args.source,
      docSha256: args.docSha256,
      found: args.found,
      at: new Date().toISOString(),
    },
  });
}

/** The field set the load record itself carries for a rate con: the
 *  fields the driver confirmed from the rate confirmation when the
 *  load was created. Used as the rate-con snapshot for a document
 *  the vision reader can't open (a PDF) and as the run-time fallback
 *  for loads that predate snapshots — labelled "confirmed" /
 *  "load_record", never presented as a fresh document read. Fields
 *  the load record doesn't carry (street addresses, pieces,
 *  reference numbers, itemized charges) stay null — missing, never
 *  reconstructed. */
function rateconFieldsFromLoadRecord(load: LoadRow): DocSideFields {
  return {
    ...EMPTY_DOC_FIELDS,
    identity: load.shipper ?? load.brokerCompany ?? load.brokerName ?? null,
    pickupCity: load.pickupCity ?? null,
    pickupState: load.pickupState ?? null,
    deliveryCity: load.deliveryCity ?? null,
    deliveryState: load.deliveryState ?? null,
    pickupWindow: load.pickupText ?? null,
    deliveryWindow: load.deliveryText ?? null,
    commodity: load.commodity ?? null,
    weightLbs: load.weightLbs ?? null,
    rate: load.rate ?? null,
    chargesTotal: load.extraCharges != null && load.extraCharges > 0 ? load.extraCharges : null,
  };
}

/** Assemble one side of a cross-verification from the load's stored
 *  records: the latest extraction snapshot for the document
 *  currently attached; failing that, the honest fallback (rate con:
 *  the load record's confirmed fields; BOL: the pickup seal check's
 *  BOL seal number — the one BOL read the app has always persisted). */
async function docSideForLoad(
  ctx: Ctx,
  load: LoadRow,
  side: "ratecon" | "bol",
): Promise<{ side: DocSide; source: string; note: string | null }> {
  const db = ctx.db<typeof schema>();
  const docSha = side === "ratecon" ? load.docSha256 : load.pickupBolSha256;
  const present = docSha != null;
  const snaps = (
    await db
      .select()
      .from(schema.loadDocExtractions)
      .where(and(eq(schema.loadDocExtractions.loadId, load.id), eq(schema.loadDocExtractions.side, side)))
      .orderBy(desc(schema.loadDocExtractions.id))
  ).filter((s) => s.docSha256 === docSha || docSha == null);
  const snap = snaps[0];
  if (snap) {
    return {
      side: { present, readFailed: !snap.found, fields: parseDocFields(snap.fieldsJson) },
      source: snap.source,
      note: snap.found
        ? null
        : `The ${side === "ratecon" ? "rate confirmation" : "BOL"} is attached, but its recorded read found no load details on it — its fields report as not readable.`,
    };
  }
  if (side === "ratecon") {
    const fields = rateconFieldsFromLoadRecord(load);
    const hasAny = Object.values(fields).some((v) => v != null);
    return {
      side: { present, readFailed: present && !hasAny, fields },
      source: "load_record",
      note: present
        ? "No document read is on record for the attached rate confirmation — the rate-con side is the field set confirmed on the load record. Street addresses, pieces, reference numbers and itemized charges aren't carried on the load record, so they report as missing."
        : "No rate confirmation document is attached — the rate-con side is the load record's confirmed fields, and the pair cannot reach verified without the document.",
    };
  }
  // BOL fallback: the pickup seal check's BOL number, when recorded.
  const fields: DocSideFields = { ...EMPTY_DOC_FIELDS, sealNumber: load.sealBol ?? null };
  return {
    side: { present, readFailed: false, fields },
    source: "load_record",
    note: present
      ? "The BOL photo is sealed, but its details were never read into a snapshot — only the seal number from the pickup seal check is on record. Other BOL fields report as not on the BOL record."
      : "No BOL photo is attached yet — the BOL is captured at the pickup step.",
  };
}

/** Open cross-verification exceptions for a load, as the seal-grade
 *  detail lines the release-grade evaluation reads. */
async function openDocExceptionDetails(ctx: Ctx, loadId: number): Promise<string[]> {
  const db = ctx.db<typeof schema>();
  const rows = await db
    .select()
    .from(schema.loadDocExceptions)
    .where(and(eq(schema.loadDocExceptions.loadId, loadId), eq(schema.loadDocExceptions.status, "open")))
    .orderBy(asc(schema.loadDocExceptions.id));
  return rows.map(
    (r) =>
      `Rate-con / BOL check: ${r.fieldLabel} differs (rate con ${r.rateconValue ?? "—"} vs BOL ${r.bolValue ?? "—"})`,
  );
}

/** Snapshot the rate-con side of a load at the moment a rate
 *  confirmation document is attached (saveLoad with a new file).
 *  When the plan covers document reading (Gold+, the loads-by-photo
 *  gate) and the file is an image, the side is the extended document
 *  read itself; otherwise — a PDF the vision reader can't open, or
 *  a plan without the read — the side is the field set the driver
 *  confirmed for that document, labelled "confirmed". Either way the
 *  snapshot is tied to the document's fingerprint, so a verification
 *  run always knows which document its rate-con side came from. */
async function captureRateconSnapshot(
  ctx: Ctx,
  args: {
    loadId: number;
    docSha256: string;
    docMime: string | null;
    docDataBase64: string;
    confirmedFields: DocSideFields;
  },
): Promise<void> {
  const isImage = args.docMime === "image/jpeg" || args.docMime === "image/png";
  if (isImage && isGoldPlan(await myPlan(ctx))) {
    const read = await extractDocFieldsExtended(
      ctx,
      args.docDataBase64,
      args.docMime as "image/jpeg" | "image/png",
    );
    if (read) {
      await recordDocExtraction(ctx, {
        loadId: args.loadId,
        side: "ratecon",
        source: "document",
        docSha256: args.docSha256,
        found: read.found,
        fields: read.fields,
      });
      return;
    }
  }
  await recordDocExtraction(ctx, {
    loadId: args.loadId,
    side: "ratecon",
    source: "confirmed",
    docSha256: args.docSha256,
    found: true,
    fields: args.confirmedFields,
  });
}

/** Who may see / act on a load's document verification. Board loads:
 *  the carrier who claimed the load, and the Owner/Dispatch seats of
 *  the board's company (the same split as the dispatch-fee reads).
 *  Every other load is a local load in this staging model — the
 *  device user is its driver of record, exactly as saveLoad /
 *  deleteLoad already treat loads. */
async function docVerificationAccess(
  ctx: Ctx,
  loadId: number,
): Promise<{ canView: boolean; canAct: boolean; me: string; role: string }> {
  const db = ctx.db<typeof schema>();
  const me = await myUsername(ctx);
  const board = (
    await db.select().from(schema.boardLoads).where(eq(schema.boardLoads.loadId, loadId)).limit(1)
  )[0];
  if (!board) return { canView: true, canAct: true, me, role: "driver" };
  const mine = await myMembership(ctx, me);
  const isCarrier = board.claimedBy === me;
  const isDesk =
    mine != null && mine.company.id === board.companyId && (mine.role === "owner" || mine.role === "dispatch");
  if (isCarrier) return { canView: true, canAct: true, me, role: "driver" };
  if (isDesk) return { canView: true, canAct: true, me, role: mine.role };
  return { canView: false, canAct: false, me, role: mine?.role ?? "none" };
}

/** Shared load-field payload for broker create/update/approve calls. */
const brokerLoadFields = {
  shipper: z.string().max(200).nullable(),
  pickupCity: z.string().max(120).nullable(),
  pickupState: z.string().max(60).nullable(),
  deliveryCity: z.string().max(120).nullable(),
  deliveryState: z.string().max(60).nullable(),
  pickupText: z.string().max(120).nullable(),
  deliveryText: z.string().max(120).nullable(),
  rate: z.number().nonnegative().max(1_000_000).nullable(),
  // Loaded miles for the automatic $/mi (migration 0080). Optional:
  // older callers omit them and the $/mi simply stays blank.
  loadedMiles: z.number().positive().max(100_000).nullable().optional(),
  milesSource: z.enum(["document", "entered", "estimate"]).nullable().optional(),
  extraCharges: z.number().nonnegative().max(1_000_000).default(0),
  extraChargesNote: z.string().max(300).nullable().default(null),
  weightLbs: z.number().int().nonnegative().max(500_000).nullable(),
  commodity: z.string().max(200).nullable(),
  hazmat: z.boolean().default(false),
  equipmentType: z.enum(["flatbed", "open_deck", "rgn", "oversized", "dry_van", "reefer", "container"]).nullable().default(null),
  notes: z.string().max(500).nullable().default(null),
};

function cleanBrokerFields(args: {
  shipper: string | null;
  pickupCity: string | null;
  pickupState: string | null;
  deliveryCity: string | null;
  deliveryState: string | null;
  pickupText: string | null;
  deliveryText: string | null;
  rate: number | null;
  loadedMiles?: number | null;
  milesSource?: string | null;
  extraCharges: number;
  extraChargesNote: string | null;
  weightLbs: number | null;
  commodity: string | null;
  hazmat: boolean;
  equipmentType: string | null;
  notes: string | null;
}) {
  const clean = (s: string | null) => (s?.trim() ? s.trim() : null);
  const miles = args.loadedMiles != null && args.loadedMiles > 0 ? Math.round(args.loadedMiles * 10) / 10 : null;
  return {
    shipper: clean(args.shipper),
    pickupCity: clean(args.pickupCity),
    pickupState: clean(args.pickupState),
    deliveryCity: clean(args.deliveryCity),
    deliveryState: clean(args.deliveryState),
    pickupText: clean(args.pickupText),
    deliveryText: clean(args.deliveryText),
    rate: args.rate,
    loadedMiles: miles,
    milesSource: miles != null ? (args.milesSource ?? "entered") : null,
    extraCharges: Math.round((args.extraCharges ?? 0) * 100) / 100,
    extraChargesNote: clean(args.extraChargesNote),
    weightLbs: args.weightLbs,
    commodity: clean(args.commodity),
    hazmat: args.hazmat,
    equipmentType: args.equipmentType,
    notes: clean(args.notes),
  };
}

