/** Miles panel windows from the LOCAL user's real trip records. The
 *  trips table holds this device's driver only (staging data model) —
 *  for any other username there are no local records and the caller
 *  says so honestly instead of inventing numbers. Windows are calendar
 *  windows in the server's local time: today, this week (from Monday),
 *  this month, this year. Miles keep their per-trip source labels
 *  (GPS / ELD odometer — <provider>) — the distinct sources across the
 *  counted trips are returned, never blended into a fake label. */
async function milesPanelFor(
  ctx: Ctx,
  _username: string,
  isMe: boolean,
  visible: boolean,
): Promise<{
  visible: boolean;
  hasLocalRecords: boolean;
  today: number | null;
  week: number | null;
  month: number | null;
  year: number | null;
  sources: string[];
  note: string | null;
}> {
  if (!isMe) {
    if (!visible) {
      return {
        visible: false,
        hasLocalRecords: false,
        today: null,
        week: null,
        month: null,
        year: null,
        sources: [],
        note: "This driver hides their miles panel — that's their choice, and no screen in the app overrides it.",
      };
    }
    return {
      visible: true,
      hasLocalRecords: false,
      today: null,
      week: null,
      month: null,
      year: null,
      sources: [],
      note: "Their miles live in their own sealed records on their device in this staging build — the panel fills in from those records at release. Nothing is estimated here.",
    };
  }
  const db = ctx.db<typeof schema>();
  const trips = await db.select().from(schema.trips);
  const now = new Date();
  const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const dow = (now.getDay() + 6) % 7; // Monday = 0
  const startOfWeek = startOfDay - dow * 86400000;
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
  const startOfYear = new Date(now.getFullYear(), 0, 1).getTime();
  const sum = (from: number) =>
    Math.round(
      trips
        .filter((t) => t.startedAt.getTime() >= from)
        .reduce((s, t) => s + t.totalMiles, 0) * 10,
    ) / 10;
  const sources = [...new Set(trips.map((t) => t.milesSource ?? "GPS"))];
  return {
    visible,
    hasLocalRecords: true,
    today: sum(startOfDay),
    week: sum(startOfWeek),
    month: sum(startOfMonth),
    year: sum(startOfYear),
    sources,
    note: visible
      ? null
      : "Your miles panel is hidden on your public profile — only you see these numbers.",
  };
}

const RANK_LADDER = ["Rookie", "Bronze", "Silver", "Gold", "Platinum", "Diamond"];
function rankOfScore(s: number | null): string | null {
  if (s == null) return null;
  return s >= 92 ? "Diamond" : s >= 80 ? "Platinum" : s >= 65 ? "Gold" : s >= 50 ? "Silver" : s >= 30 ? "Bronze" : "Rookie";
}

/** Season rank + all-time-best for the LOCAL user, computed with the
 *  same formulas as getDriverStats (current season: Safety with the
 *  Academy core-deduction on premium plans; Reliability from sealed
 *  deliveries + trips + on-time; past seasons archived with the same
 *  finals math). Returns nulls when the driver has no records yet. */
async function rankSummaryFor(ctx: Ctx): Promise<{
  overallRank: string | null;
  seasonNumber: number;
  allTimeBest: { rank: string; seasonNumber: number } | null;
}> {
  const db = ctx.db<typeof schema>();
  const me = await myUsername(ctx);
  const season = seasonInfo(Date.now());
  const seasonStart = season.start;
  const trips = await db.select().from(schema.trips);
  const chain = await db
    .select()
    .from(schema.chainLog)
    .orderBy(asc(schema.chainLog.id));
  const loads = await db.select().from(schema.loads);
  const loadById = new Map(loads.map((l) => [l.id, l]));
  const sealedAtByLoad = new Map<number, string>();
  for (const r of chain) {
    if (r.event === "pod_seal" && r.refId != null) {
      try {
        const p = JSON.parse(r.payload) as { at?: string };
        if (p.at) sealedAtByLoad.set(r.refId, p.at);
      } catch { /* ignore */ }
    }
    if (r.event === "pod_seal_void" && r.refId != null) sealedAtByLoad.delete(r.refId);
  }
  const sealMsByLoad = new Map<number, number>();
  for (const [id, at] of sealedAtByLoad) sealMsByLoad.set(id, Date.parse(at));
  const plan = await myPlan(ctx);
  const premium = isDiamondPlan(plan);
  const training = await trainingStatusFor(ctx, me);
  const coreDue = training.courses.filter((c) => c.core && c.status === "due").length;
  const weekAgo = Date.now() - 7 * 86400000;
  const overspeed7d = chain.filter(
    (r) => r.event === "overspeed" && r.createdAt.getTime() >= weekAgo && r.createdAt.getTime() >= seasonStart,
  ).length;
  const tripsSeason = trips.filter((t) => t.startedAt.getTime() >= seasonStart);
  const sealsSeason = [...sealMsByLoad.values()].filter((ms) => ms >= seasonStart);
  const hasData =
    tripsSeason.length > 0 || sealsSeason.length > 0 || overspeed7d > 0 || training.completions.length > 0;
  const safetyScore = hasData
    ? Math.max(0, Math.min(100, 100 - 3 * overspeed7d - (premium ? 5 * coreDue : 0)))
    : null;
  let reliabilityScore: number | null = null;
  if (tripsSeason.length > 0 || sealsSeason.length > 0) {
    let score = 50 + 2 * sealsSeason.length + tripsSeason.length;
    let oT = 0;
    let cT = 0;
    for (const [loadId, ms] of sealMsByLoad) {
      if (ms < seasonStart) continue;
      const load = loadById.get(loadId);
      if (!load?.deliveryText) continue;
      const appt = Date.parse(load.deliveryText);
      if (!Number.isFinite(appt)) continue;
      cT++;
      if (ms <= appt + 60 * 60000) oT++;
    }
    if (cT > 0 && Math.round((oT / cT) * 100) >= 90) score += 10;
    reliabilityScore = Math.min(100, score);
  }
  const overallScore =
    safetyScore != null && reliabilityScore != null
      ? Math.min(safetyScore, reliabilityScore)
      : (safetyScore ?? reliabilityScore);
  const overallRank = rankOfScore(overallScore);
  // Past seasons (archived finals, same math as getDriverStats).
  const overspeedTimes = chain
    .filter((r) => r.event === "overspeed")
    .map((r) => r.createdAt.getTime());
  let allTimeBest: { rank: string; seasonNumber: number } | null = null;
  const consider = (rank: string | null, seasonNumber: number) => {
    if (!rank) return;
    if (!allTimeBest || RANK_LADDER.indexOf(rank) > RANK_LADDER.indexOf(allTimeBest.rank)) {
      allTimeBest = { rank, seasonNumber };
    }
  };
  for (let idx = 0; idx < season.idx; idx++) {
    const s = SEASON_EPOCH + idx * SEASON_MS;
    const e = s + SEASON_MS;
    const sTrips = trips.filter((t) => t.startedAt.getTime() >= s && t.startedAt.getTime() < e);
    const sSeals = [...sealMsByLoad.entries()].filter(([, ms]) => ms >= s && ms < e);
    const sOverFinal = overspeedTimes.filter((t) => t >= e - 7 * 86400000 && t < e).length;
    const sOverAny = overspeedTimes.filter((t) => t >= s && t < e).length;
    if (sTrips.length === 0 && sSeals.length === 0 && sOverAny === 0) continue;
    const sSafety = Math.max(0, Math.min(100, 100 - 3 * sOverFinal));
    let sReliability: number | null = null;
    if (sTrips.length > 0 || sSeals.length > 0) {
      let sc = 50 + 2 * sSeals.length + sTrips.length;
      let oT = 0;
      let cT = 0;
      for (const [loadId, ms] of sSeals) {
        const load = loadById.get(loadId);
        if (!load?.deliveryText) continue;
        const appt = Date.parse(load.deliveryText);
        if (!Number.isFinite(appt)) continue;
        cT++;
        if (ms <= appt + 60 * 60000) oT++;
      }
      if (cT > 0 && Math.round((oT / cT) * 100) >= 90) sc += 10;
      sReliability = Math.min(100, sc);
    }
    const sOverall =
      sReliability != null ? Math.min(sSafety, sReliability) : sSafety;
    consider(rankOfScore(sOverall), idx + 1);
  }
  consider(overallRank, season.number);
  return { overallRank, seasonNumber: season.number, allTimeBest };
}

/** DM membership check — the enforcement half of the owner's standing
 *  rule: NOBODY can see individual DMs (not owners, not admins, not
 *  other drivers). A DM group's messages are readable/writable ONLY by
 *  its two members. Company chats carry a companyId and are a separate,
 *  company-visible domain by design; this check applies to kind "dm"
 *  only and no owner/admin role ever bypasses it. */
async function dmMembership(
  ctx: Ctx,
  groupId: number,
): Promise<{ isDm: boolean; isMember: boolean; me: string }> {
  const db = ctx.db<typeof schema>();
  const me = await myUsername(ctx);
  const groups = await db
    .select()
    .from(schema.chatGroups)
    .where(eq(schema.chatGroups.id, groupId))
    .limit(1);
  const g = groups[0];
  if (!g || g.kind !== "dm") return { isDm: false, isMember: true, me };
  const members = await db
    .select()
    .from(schema.chatMembers)
    .where(eq(schema.chatMembers.groupId, groupId));
  return {
    isDm: true,
    isMember: members.some((m) => m.username.toLowerCase() === me.toLowerCase()),
    me,
  };
}

// ---- Shipper Portal (migration 0069) ---------------------------------------
// RUGGS LOGISTICS is the dispatch desk; the portal is its front door.
// A shipper posts a load in about three clicks under its own name; the
// load lands in the Owner Console review queue and nothing reaches
// the Fleet Board until the desk releases it — releasing inserts a
// normal board_loads row through the same field shape postBoardLoad
// uses, so claim → sealed POD → auto-invoice runs unchanged. HARD
// RULES, enforced in the shapes themselves: no payment field exists
// anywhere in the portal, and no shipper-facing shape carries any
// dispatch-fee or internal percentage information — shipper shapes are
// built field-by-field below and never spread a board/load row.
// DATA WALL (absolute, server-side): the caller's shipper account is
// resolved from shipper_accounts.linked_username === myUsername —
// never from a client-supplied shipper id — and every shipper read
// filters on that account's id. The desk side resolves from the
// caller's company membership (Owner/Dispatch), exactly like the
// board. A shipper id from another account answers as not found.

// ---- Open Board shapes + vetted gate (migration 0073) ----------------------
// The Open Board carries loads that left a single fleet: broker loads
// released from the Broker Portal and fleet overflow. Its shape is
// built field-by-field like the portal shapes. It carries NO field
// for the RUGGS LLC house dispatch fee: that fee is the claiming
// carrier's own invoice (visible to them in their dispatch-fee
// panel), never a number the origin or the board negotiates. It
// DOES carry the POSTER's own dispatcher fee % (migration 0088,
// round 2, x 2026-11-02): a dispatcher who posts a load sets their
// own fee (0–20), and the claiming carrier sees it on the card,
// beside the poster's name, BEFORE claiming — the two fees are
// different charges by different parties and are never conflated.

