/** VETTED OWNER OPERATOR — the gate for the Open Board (x, 2026-10-30).
 *  The standard is the app's existing credential standard for load
 *  access beyond a fleet (the same one that gates broker uploads):
 *  Diamond-tier access (Diamond Driver or the Owner plan — fleet
 *  drivers ride on their fleet's included Diamond) AND running your
 *  own operation — a solo owner-operator (no company membership) or a
 *  fleet OWNER claiming for themselves. Employee drivers and dispatch
 *  seats in someone else's fleet are never vetted owner operators:
 *  their board is their fleet's board. Reasons are returned in plain
 *  words so the UI can say exactly what vetting takes. */
async function vettedStatusFor(
  ctx: Ctx,
  username: string,
): Promise<{ vetted: boolean; reasons: string[]; kycStatus: string }> {
  const db = ctx.db<typeof schema>();
  const reasons: string[] = [];
  const { plan, diamond } = await hasDiamondAccess(ctx);
  if (!diamond) {
    reasons.push(
      `Vetting takes Diamond-tier access — this account is on ${planLabel(plan)}. Diamond Driver (owner-operators) or the Owner fleet plan carries it; Gold and Basic don't include the Open Board.`,
    );
  }
  const mine = await myMembership(ctx, username);
  if (mine && mine.role === "driver") {
    reasons.push(
      `You're a driver in ${mine.company.name} — vetted owner operators run their own authority. Your fleet's loads are on your Fleet Board; the Open Board is for owner operators claiming under their own name.`,
    );
  } else if (mine && mine.role === "dispatch") {
    reasons.push("Dispatch seats don't haul loads — the Open Board is claimed by vetted owner operators running their own trucks.");
  }
  const prof = await db.select().from(schema.profile).where(eq(schema.profile.id, myProfileId(ctx))).limit(1);
  return { vetted: reasons.length === 0, reasons, kycStatus: prof[0]?.kycStatus ?? "not_started" };
}

