/** What a load still needs before it can be SENT to dispatch. A load
 *  missing any of these can only ever save as a draft — the send
 *  action re-checks this server-side, so no client can slip a
 *  half-ready load into the review queue. */
function shipperMissingForSend(row: ShipperLoadRow): string[] {
  const missing: string[] = [];
  if (row.rate == null || row.rate <= 0) missing.push("the rate");
  if (!row.rateConBlobKey) missing.push("the rate confirmation attached (PDF or photo)");
  if (!row.signoffConfirmed) missing.push("the customer sign-off confirmation");
  if (!row.offloadConfirmed) missing.push("the offload-equipment confirmation");
  return missing;
}

/** Build the shipper-facing shape for one portal load. For released
 *  loads the plain status + carrier + POD facts are derived LIVE from
 *  the board row and its claimed driver load — the same records the
 *  board itself reads — so the shipper's list can never drift from
 *  the load's real state. Carrier phone: the number the carrier added
 *  to their own profile (social_users.contact_phone, migration 0082),
 *  read from the same profile row as the carrier's name — and ONLY
 *  inside the board.status === "taken" branch, so a phone can only
 *  ever surface on a load that carrier has already claimed. Before a
 *  claim it answers null, and a carrier who never added one answers
 *  null too — the UI says "not on file" plainly, never invented. */
async function toShipperLoad(
  ctx: Ctx,
  row: ShipperLoadRow,
  account: ShipperAccountRow,
  pods: Map<number, PodInfo>,
): Promise<z.infer<typeof shipperLoadShape>> {
  const db = ctx.db<typeof schema>();
  let plainStatus = "Draft";
  let carrierName: string | null = null;
  let carrierUsername: string | null = null;
  let carrierPhone: string | null = null;
  let carrierEmail: string | null = null;
  let carrierMcNumber: string | null = null;
  let carrierDotNumber: string | null = null;
  let carrierSaferUrl: string | null = null;
  let carrierTwicHas = false;
  let carrierTwicExpires: string | null = null;
  let carrierEndorsements: EndorsementKey[] = [];
  let podSealed = false;
  let podSealedAt: string | null = null;
  let podSealHash: string | null = null;
  let hasBol = false;
  if (row.status === "returned") plainStatus = "Returned — needs fixes";
  if (row.status === "sent") plainStatus = "With dispatch";
  if (row.status === "released" && row.boardLoadId != null) {
    plainStatus = "On the board";
    const boards = await db
      .select()
      .from(schema.boardLoads)
      .where(eq(schema.boardLoads.id, row.boardLoadId))
      .limit(1);
    const board = boards[0];
    if (!board) {
      // Released, then pulled off the board by dispatch — the load is
      // back in the desk's hands, which is what the shipper reads.
      plainStatus = "With dispatch";
    }
    if (board && board.status === "taken") {
      carrierUsername = board.claimedBy ?? null;
      if (board.loadId != null) {
        const pod = pods.get(board.loadId);
        podSealed = pod?.sealed ?? false;
        podSealedAt = pod?.sealedAt ?? null;
        podSealHash = pod?.sealHash ?? null;
        const loadRows = await db.select().from(schema.loads).where(eq(schema.loads.id, board.loadId)).limit(1);
        const load = loadRows[0];
        hasBol = load?.pickupBolBlobKey != null;
        if (podSealed) plainStatus = "Delivered";
        else if (load?.status === "picked_up" && load?.pickupSealedAt != null) plainStatus = "In transit";
        else if (load?.status === "picked_up") plainStatus = "Picked up";
        else plainStatus = "Carrier assigned";
      } else {
        plainStatus = "Carrier assigned";
      }
      if (carrierUsername) {
        const social = await db
          .select()
          .from(schema.socialUsers)
          .where(eq(schema.socialUsers.username, carrierUsername))
          .limit(1);
        carrierName = social[0]?.displayName ?? carrierUsername;
        // Claim-gated by construction: this lookup runs only for the
        // carrier who claimed THIS load, so no other carrier's phone
        // can ever ride this shape.
        carrierPhone = social[0]?.contactPhone ?? null;
        // Same gate, same row (migration 0083): the carrier's contact
        // email rides with the phone, and their public credentials —
        // MC / DOT, the SAFER Web link built from those numbers,
        // TWIC holding + expiry, CDL endorsements — come along so
        // the shipper can vet the carrier hauling their load. The
        // SAFER value is a link to the official FMCSA record only.
        carrierEmail = social[0]?.contactEmail ?? null;
        carrierMcNumber = social[0]?.mcNumber ?? null;
        carrierDotNumber = social[0]?.dotNumber ?? null;
        carrierSaferUrl = saferUrlFor({
          dotNumber: social[0]?.dotNumber ?? null,
          mcNumber: social[0]?.mcNumber ?? null,
        });
        carrierTwicHas = social[0]?.twicHas ?? false;
        carrierTwicExpires = social[0]?.twicExpires ?? null;
        carrierEndorsements = parseEndorsements(social[0]?.endorsements);
      }
    }
  }
  return {
    id: row.id,
    shipperId: row.shipperId,
    shipperName: account.name,
    referenceNumber: row.referenceNumber ?? null,
    pickupAddress: row.pickupAddress ?? null,
    pickupCity: row.pickupCity ?? null,
    pickupState: row.pickupState ?? null,
    pickupDate: row.pickupDate ?? null,
    pickupWindow: row.pickupWindow ?? null,
    deliveryAddress: row.deliveryAddress ?? null,
    deliveryCity: row.deliveryCity ?? null,
    deliveryState: row.deliveryState ?? null,
    deliveryDate: row.deliveryDate ?? null,
    deliveryWindow: row.deliveryWindow ?? null,
    commodity: row.commodity ?? null,
    freightClass: row.freightClass ?? null,
    weightLbs: row.weightLbs ?? null,
    pieces: row.pieces ?? null,
    dimensions: row.dimensions ?? null,
    equipment: row.equipment ?? null,
    equipmentLabel: row.equipment ? (SHIPPER_EQUIPMENT_LABELS[row.equipment] ?? row.equipment) : null,
    tarps: row.tarps ?? false,
    edgeProtectors: row.edgeProtectors ?? false,
    rate: row.rate ?? null,
    hasRateCon: row.rateConBlobKey != null,
    rateConSha256: row.rateConSha256 ?? null,
    rateConMime: row.rateConMime ?? null,
    signoffConfirmed: row.signoffConfirmed ?? false,
    offloadConfirmed: row.offloadConfirmed ?? false,
    contactName: row.contactName ?? null,
    contactPhone: row.contactPhone ?? null,
    notes: row.notes ?? null,
    status: row.status,
    plainStatus,
    missingForSend: shipperMissingForSend(row),
    boardLoadId: row.boardLoadId ?? null,
    trackToken: row.trackToken ?? null,
    carrierName,
    carrierUsername,
    carrierPhone,
    carrierEmail,
    carrierMcNumber,
    carrierDotNumber,
    carrierSaferUrl,
    carrierTwicHas,
    carrierTwicExpires,
    carrierEndorsements,
    podSealed,
    podSealedAt,
    podSealHash,
    hasBol,
    reviewNote: row.reviewNote ?? null,
    reviewedBy: row.reviewedBy ?? null,
    reviewedAt: row.reviewedAt?.toISOString() ?? null,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

/** The desk context for the portal: the caller's company membership
 *  with an Owner/Dispatch seat. Shipper accounts belong to that
 *  company's desk (companyId on the account). */
async function shipperDeskContext(ctx: Ctx): Promise<{
  me: string;
  membership: Awaited<ReturnType<typeof myMembership>>;
  isDesk: boolean;
} | null> {
  const me = await myUsername(ctx);
  const membership = await myMembership(ctx, me);
  const isDesk = membership != null && (membership.role === "owner" || membership.role === "dispatch");
  return { me, membership, isDesk };
}

const shipperLoadFieldsRequest = {
  referenceNumber: z.string().max(80).nullable().default(null),
  pickupAddress: z.string().max(300).nullable().default(null),
  pickupCity: z.string().max(120).nullable().default(null),
  pickupState: z.string().max(60).nullable().default(null),
  pickupDate: z.string().max(40).nullable().default(null),
  pickupWindow: z.string().max(80).nullable().default(null),
  deliveryAddress: z.string().max(300).nullable().default(null),
  deliveryCity: z.string().max(120).nullable().default(null),
  deliveryState: z.string().max(60).nullable().default(null),
  deliveryDate: z.string().max(40).nullable().default(null),
  deliveryWindow: z.string().max(80).nullable().default(null),
  commodity: z.string().max(200).nullable().default(null),
  freightClass: z.string().max(40).nullable().default(null),
  weightLbs: z.number().int().nonnegative().max(500_000).nullable().default(null),
  pieces: z.number().int().nonnegative().max(100_000).nullable().default(null),
  dimensions: z.string().max(120).nullable().default(null),
  equipment: z.enum(["flatbed", "step_deck", "rgn"]).nullable().default(null),
  tarps: z.boolean().default(false),
  edgeProtectors: z.boolean().default(false),
  rate: z.number().nonnegative().max(1_000_000).nullable().default(null),
  signoffConfirmed: z.boolean().default(false),
  offloadConfirmed: z.boolean().default(false),
  contactName: z.string().max(120).nullable().default(null),
  contactPhone: z.string().max(40).nullable().default(null),
  notes: z.string().max(1000).nullable().default(null),
  docDataBase64: z.string().max(14_000_000).nullable().default(null),
  docMime: z.string().max(100).nullable().default(null),
};

function cleanShipperFields(args: Record<string, unknown>): Record<string, unknown> {
  const clean = (v: unknown) => (typeof v === "string" ? (v.trim() ? v.trim() : null) : v);
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(args)) {
    if (k === "docDataBase64" || k === "docMime" || k === "id" || k === "send") continue;
    out[k] = clean(v);
  }
  return out;
}

// ---- Broker Portal — poster accounts (migration 0073) ----------------------
// The broker twin of the Shipper Portal, on the same rails: the desk
// invites and approves broker accounts; a broker posts loads under
// its own name and logo; every load lands in the Owner Console review
// queue first and nothing hits a board until the desk releases it —
// and a release puts the load on the OPEN board (vetted owner
// operators only), not a fleet board. Same gates as the Shipper
// Portal: rate + rate confirmation required (otherwise draft only),
// customer sign-off and offload-equipment confirmations, no fee
// numbers on any broker-facing surface (broker shapes are built
// field-by-field and carry no fee field), and RUGGS LLC never touches
// freight money — pay runs direct from the broker to the carrier.
// ROUND 2 EXCEPTION (x, 2026-11-02): the poster's OWN dispatcher fee
// % IS theirs to set and see (dispatcherFeePct below) — it is their
// own number, shown to carriers on their loads before claiming.
// The rule above still bars every OTHER fee: the RUGGS LLC house
// fee and all internal percentages never appear here.
// DATA WALL (absolute, server-side): the caller's broker account is
// resolved from broker_accounts.linked_username === myUsername —
// never from a client-supplied broker id.

const brokerAccountShape = z.object({
  id: z.number(),
  name: z.string(),
  email: z.string(),
  contactName: z.string().nullable(),
  logoInitials: z.string().nullable(),
  brokerMc: z.string().nullable(),
  // The poster's OWN dispatcher fee % override (migration 0088) —
  // see the section comment: their number, set by them or their
  // desk, capped at 20. Null = unset (inherits the dispatch
  // company's fee when linked to one, else no fee).
  dispatcherFeePct: z.number().nullable(),
  linkedUsername: z.string().nullable(),
  status: z.string(), // active | suspended
  isDemo: z.boolean(),
  defaultPickupAddress: z.string().nullable(),
  defaultPickupCity: z.string().nullable(),
  defaultPickupState: z.string().nullable(),
  defaultCommodity: z.string().nullable(),
  defaultFreightClass: z.string().nullable(),
  defaultContactName: z.string().nullable(),
  defaultContactPhone: z.string().nullable(),
  loadCount: z.number(),
  createdAt: z.string(),
});

const brokerLoadShape = z.object({
  id: z.number(),
  brokerId: z.number(),
  brokerName: z.string(),
  brokerMc: z.string().nullable(),
  referenceNumber: z.string().nullable(),
  pickupAddress: z.string().nullable(),
  pickupCity: z.string().nullable(),
  pickupState: z.string().nullable(),
  pickupDate: z.string().nullable(),
  pickupWindow: z.string().nullable(),
  deliveryAddress: z.string().nullable(),
  deliveryCity: z.string().nullable(),
  deliveryState: z.string().nullable(),
  deliveryDate: z.string().nullable(),
  deliveryWindow: z.string().nullable(),
  commodity: z.string().nullable(),
  freightClass: z.string().nullable(),
  weightLbs: z.number().nullable(),
  pieces: z.number().nullable(),
  dimensions: z.string().nullable(),
  equipment: z.string().nullable(), // flatbed | step_deck | rgn
  equipmentLabel: z.string().nullable(),
  tarps: z.boolean(),
  edgeProtectors: z.boolean(),
  rate: z.number().nullable(),
  hasRateCon: z.boolean(),
  rateConSha256: z.string().nullable(),
  rateConMime: z.string().nullable(),
  signoffConfirmed: z.boolean(),
  offloadConfirmed: z.boolean(),
  contactName: z.string().nullable(),
  contactPhone: z.string().nullable(),
  notes: z.string().nullable(),
  // draft | sent | returned | released (the stored lifecycle)
  status: z.string(),
  // Plain-words status the broker reads: Draft | Returned — needs
  // fixes | With dispatch | On the open board | Carrier assigned |
  // Picked up | In transit | Delivered
  plainStatus: z.string(),
  missingForSend: z.array(z.string()),
  boardLoadId: z.number().nullable(),
  trackToken: z.string().nullable(),
  carrierName: z.string().nullable(),
  carrierUsername: z.string().nullable(),
  carrierPhone: z.string().nullable(),
  // Carrier credentials (migration 0083): same claim-gated read as
  // the Shipper Portal shape — see shipperLoadShape. carrierSaferUrl
  // links to the carrier's official FMCSA SAFER Web record; no score
  // is ever computed or shown.
  carrierEmail: z.string().nullable(),
  carrierMcNumber: z.string().nullable(),
  carrierDotNumber: z.string().nullable(),
  carrierSaferUrl: z.string().nullable(),
  carrierTwicHas: z.boolean(),
  carrierTwicExpires: z.string().nullable(),
  carrierEndorsements: z.array(endorsementKeySchema),
  podSealed: z.boolean(),
  podSealedAt: z.string().nullable(),
  podSealHash: z.string().nullable(),
  hasBol: z.boolean(),
  reviewNote: z.string().nullable(),
  reviewedBy: z.string().nullable(),
  reviewedAt: z.string().nullable(),
  createdAt: z.string(),
  updatedAt: z.string(),
});

type BrokerAccountRow = typeof schema.brokerAccounts.$inferSelect;
type BrokerPosterLoadRow = typeof schema.brokerPosterLoads.$inferSelect;

