      if (!known.includes(args.username)) return { ok: false, error: "No account with that username is on record.", code: null };
      // A resend mints a FRESH single-use driver invite (the old ones
      // may be lost in an inbox); the code is returned to the team
      // member to send — it is never written into the audit detail.
      const fresh = await mintBetaDriverCode(ctx);
      await db.insert(schema.betaCodes).values({ code: fresh, kind: "driver", singleUse: true, revoked: false });
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "beta_code_issued",
        payload: { code: fresh, kind: "driver", via: "team_portal_resend", forUsername: args.username, at: new Date().toISOString() },
      });
      await teamLog(ctx, mine.me, "resend_invite", args.username, `Fresh driver invite code issued for @${args.username} (resend).`);
      ctx.invalidateQueries();
      return { ok: true, error: null, code: fresh };
