        if (!row) return { ok: false, error: "That broker account doesn't exist." };
        await db.update(schema.brokerAccounts).set({ status: args.status, updatedAt: now }).where(eq(schema.brokerAccounts.id, args.id));
        await teamLog(
          ctx,
          mine.me,
          "portal_account_status",
          row.linkedUsername,
          `Broker portal account "${row.name}": ${row.status} → ${args.status} (${args.status === "active" ? "approved" : "suspended"}).`,
        );
