      const fields = cleanShipperFields(args as unknown as Record<string, unknown>) as Partial<BrokerPosterLoadRow>;
      await db
        .update(schema.brokerPosterLoads)
        .set({ ...fields, updatedAt: new Date() })
        .where(eq(schema.brokerPosterLoads.id, args.id));
